
using LinksAudio.Core;
using LinksAudio.Codecs;
using System.Text.Json;
using NAudio.Wave;
var root=Path.GetFullPath(args[0]);var fixture=Path.Combine(root,"tests/Fixtures");var output=Path.Combine(root,"tests/output/engine-"+DateTime.Now.ToString("yyyyMMdd-HHmmss"));Directory.CreateDirectory(fixture);Directory.CreateDirectory(output);
var source=File.ReadAllBytes(Path.Combine(root,"tests/Fixtures/synthetic-tone.silk"));
var packets=SilkDecoder.Packets(source);int start=source[0]==2?10:9;int end=packets[^1].Offset+packets[^1].Length;
 // Container variants use an generated, non-speech SILK payload.
byte[] st=[.."#!SILK_V3"u8.ToArray(),..source[start..end],255,255];byte[] tx=[2,.."#!SILK_V3"u8.ToArray(),..source[start..end]];
File.WriteAllBytes(Path.Combine(fixture,"standard.silk"),st);File.WriteAllBytes(Path.Combine(fixture,"合成测试.amr"),tx);File.WriteAllBytes(Path.Combine(fixture,"empty.amr"),[]);File.WriteAllBytes(Path.Combine(fixture,"truncated.silk"),tx[..^7]);
var engine=new AudioEngine();var results=new List<object>();int fails=0;
void Assert(bool cond,string message){if(!cond)throw new Exception(message);}
async Task Test(string name,Func<Task<string>> test){try{var details=await test();Console.WriteLine("PASS "+name+" "+details);results.Add(new{name,status="PASS",details});}catch(Exception e){fails++;Console.WriteLine("FAIL "+name+" "+e);results.Add(new{name,status="FAIL",details=e.ToString()});}}
async Task Reject(string file,ConversionOptions? options=null){bool rejected=false;try{await engine.ConvertAsync(file,options??new(output));}catch(Exception){rejected=true;}Assert(rejected,"预期失败但转换成功");}
await Test("native_vs_original_reference",()=>{using var pcm=new MemoryStream();SilkDecoder.Decode(source,pcm);var actual=pcm.ToArray();var reference=File.ReadAllBytes(Path.Combine(root,"tests/Fixtures/reference.pcm"));Assert(actual.SequenceEqual(reference),"与原始 SDK 参考 PCM 不一致");File.WriteAllBytes(Path.Combine(output,"native.pcm"),actual);return Task.FromResult($"PCM byte identical, {actual.Length} bytes, {actual.Length/48000.0:F3} s");});
foreach(var name in new[]{"standard.silk","合成测试.amr"})foreach(var format in new[]{"WAV","MP3"})await Test(name+"_to_"+format,async()=>{var r=await engine.ConvertAsync(Path.Combine(fixture,name),new(output,format));Assert(Math.Abs(r.Duration.TotalSeconds-6.56)<.3,"时长异常");return $"{r.Duration.TotalSeconds:F3} s; {r.Encoder}";});
await Test("forced_LAME_fallback",async()=>{var r=await engine.ConvertAsync(Path.Combine(fixture,"standard.silk"),new(output,ForceLame:true));return $"{r.Encoder}; {r.Duration.TotalSeconds:F3} s";});
await Test("WAV_input_to_MP3",async()=>{var r=await engine.ConvertAsync(Directory.GetFiles(output,"*.wav")[0],new(output));return r.Path;});
await Test("MP3_input_to_WAV",async()=>{var r=await engine.ConvertAsync(Directory.GetFiles(output,"*.mp3")[0],new(output,"WAV"));return r.Path;});
await Test("empty",async()=>{await Reject(Path.Combine(fixture,"empty.amr"));return "rejected";});
await Test("truncated",async()=>{await Reject(Path.Combine(fixture,"truncated.silk"));return "rejected";});
await Test("damaged_header",async()=>{var file=Path.Combine(fixture,"bad.aud");File.WriteAllText(file,"garbage not audio");await Reject(file);return "rejected";});
await Test("corrupt_payload",async()=>{var file=Path.Combine(fixture,"corrupt.silk");File.WriteAllBytes(file,[.."#!SILK_V3"u8.ToArray(),1,0,255,255,255]);await Reject(file);return "rejected";});
foreach(var (name,header,kind) in new[]{("amrnb","#!AMR\n",AudioKind.AmrNb),("amrwb","#!AMR-WB\n",AudioKind.AmrWb)})await Test(name+"_detected",async()=>{var b=System.Text.Encoding.ASCII.GetBytes(header);Assert(AudioEngine.Detect(b)==kind,"AMR 检测错误");var file=Path.Combine(fixture,name+".amr");File.WriteAllBytes(file,b);await Reject(file);return "recognized; explicitly unsupported backend (header-only fixture)";});
await Test("unicode_paths",async()=>{var dir=Path.Combine(output,"中文目录_é_音频_𝄞");Directory.CreateDirectory(dir);var file=Path.Combine(dir,"语音_测试.amr");File.WriteAllBytes(file,tx);var r=await engine.ConvertAsync(file,new(dir,"WAV"));return r.Path;});
await Test("long_paths",async()=>{var dir=Path.Combine(output,new string('a',100),new string('b',100),new string('c',50));Directory.CreateDirectory(dir);var file=Path.Combine(dir,"长路径.amr");File.WriteAllBytes(file,tx);var r=await engine.ConvertAsync(file,new(dir,"WAV"));Assert(r.Path.Length>260,"路径不够长");return $"path chars {r.Path.Length}";});
await Test("duplicate_names",async()=>{var dir=Path.Combine(output,"duplicates");var a=await engine.ConvertAsync(Path.Combine(fixture,"standard.silk"),new(dir));var b=await engine.ConvertAsync(Path.Combine(fixture,"standard.silk"),new(dir));Assert(a.Path!=b.Path,"覆盖重复文件");return Path.GetFileName(b.Path);});
await Test("overwrite_preserves_input",async()=>{var dir=Path.Combine(output,"original");Directory.CreateDirectory(dir);var original=Path.Combine(dir,"voice.wav");File.Copy(Directory.GetFiles(output,"*.wav")[0],original);var bytes=File.ReadAllBytes(original);var r=await engine.ConvertAsync(original,new(dir,"WAV",Overwrite:true));Assert(r.Path!=original&&bytes.SequenceEqual(File.ReadAllBytes(original)),"原件被修改");return Path.GetFileName(r.Path);});
await Test("cancel_before_start",async()=>{using var c=new CancellationTokenSource();c.Cancel();try{await engine.ConvertAsync(Path.Combine(fixture,"standard.silk"),new(output),c.Token);throw new Exception("未取消");}catch(OperationCanceledException){return "cancelled";}});
await Test("cancel_during_decode",async()=>{var dir=Path.Combine(output,"cancel");using var c=new CancellationTokenSource();bool cancelled=false;try{await engine.ConvertAsync(Path.Combine(fixture,"standard.silk"),new(dir),c.Token,p=>{if(p>.01)c.Cancel();});}catch(OperationCanceledException){cancelled=true;}Assert(cancelled,"未取消");Assert(!Directory.EnumerateFiles(dir).Any(),"留下临时或假成功文件");return "cancelled; no output";});
await Test("cancel_after_encoding",async()=>{var dir=Path.Combine(output,"cancel-after-encode");using var c=new CancellationTokenSource();bool cancelled=false;try{await engine.ConvertAsync(Path.Combine(fixture,"standard.silk"),new(dir),c.Token,p=>{if(p>=.8)c.Cancel();});}catch(OperationCanceledException){cancelled=true;}Assert(cancelled,"未取消");Assert(!Directory.EnumerateFiles(dir).Any(),"留下输出");return "staged MP3 removed before commit";});
await Test("unwritable_output",async()=>{var file=Path.Combine(output,"not-a-directory");File.WriteAllText(file,"blocker");await Reject(Path.Combine(fixture,"standard.silk"),new(file));return "rejected";});
await Test("locked_input",async()=>{var file=Path.Combine(fixture,"standard.silk");using var locked=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.None);await Reject(file);return "rejected";});
await Test("batch_partial_success",async()=>{int ok=0,bad=0;foreach(var file in new[]{"standard.silk","empty.amr","合成测试.amr"}){try{await engine.ConvertAsync(Path.Combine(fixture,file),new(Path.Combine(output,"batch")));ok++;}catch{bad++;}}Assert(ok==2&&bad==1,"批量状态错误");return "2 success, 1 rejected";});
await Test("sample_rate_resampling",()=>{foreach(var rate in new[]{8000,12000,16000,24000,48000}){using var ms=new MemoryStream();SilkDecoder.Decode(tx,ms,rate);Assert(Math.Abs(ms.Length/(rate*2.0)-6.56)<.01,"重采样时长异常");}return Task.FromResult("8/12/16/24/48 kHz, duration invariant 6.560 s");});
await Test("source_unchanged",()=>{Assert(source.SequenceEqual(File.ReadAllBytes(Path.Combine(root,"tests/Fixtures/synthetic-tone.silk"))),"原始样本已修改");return Task.FromResult("byte identical");});
File.WriteAllText(Path.Combine(root,"tests/output/results.json"),JsonSerializer.Serialize(new{run=DateTimeOffset.Now,output,tests=results,failures=fails},new JsonSerializerOptions{WriteIndented=true}));Environment.ExitCode=fails==0?0:1;
